<div class="content"><article class="article">{!! $html !!}</article><section class="example" aria-label="Esempio di richiesta"><div class="example-head"><span>cURL · Backend</span><button id="copy">Copia</button></div><pre id="code">{{ $example }}</pre><footer>Usa una variabile di ambiente per il token.<br><a href="/developers/authentication">Autenticazione e credenziali</a></footer></section></div></main></div>
<script>
document.getElementById('menu').addEventListener('click',function(){const open=document.getElementById('navigation').classList.toggle('open');this.setAttribute('aria-expanded',String(open));});
document.getElementById('search').addEventListener('input',function(){let count=0;document.querySelectorAll('[data-nav]').forEach(a=>{a.hidden=!a.textContent.toLocaleLowerCase('it').includes(this.value.trim().toLocaleLowerCase('it'));if(!a.hidden)count++;});document.getElementById('empty').hidden=count>0;});
document.getElementById('copy').addEventListener('click',async function(){try{await navigator.clipboard.writeText(document.getElementById('code').textContent);this.textContent='Copiato';}catch{this.textContent='Copia non riuscita';}setTimeout(()=>this.textContent='Copia',2000);});
</script>
